Lemma rdn_nth (segs : list Segment) (M : word -> option byte) : forall (n : nat) a bs, rdn segs M (Z_to_bv 64 a) n = Some bs ->
  forall i, (i < n)%nat -> M (Z_to_bv 64 (a + Z.of_nat i)) <> None -> M (Z_to_bv 64 (a + Z.of_nat i)) = nth_error bs i.
