Lemma pstate_copy (segs : list Segment) (M M' : word -> option byte) a b s :
  (forall i, 0 <= i < 32 -> M (Z_to_bv 64 (a + i)) <> None /\ M' (Z_to_bv 64 (b + i)) = M (Z_to_bv 64 (a + i))) ->
  PM.pstate_at segs M a s -> PM.pstate_at segs M' b s.
